import SEED from "./seed.json";
import type { ActivationSection, CellValue, Column, Lane } from "./model";

/**
 * THE FIRST VERSION OF THE PLAN — the two Google Sheets, merged (v36.7).
 *
 *   "Activate"      → Timeline + Checkpoints
 *   "Activate 26'"  → Structure & JDs, Mapping, HR Plan, OC-TimeLine1
 *
 * seed.json is generated by a one-off script from the sheets' xlsx exports.
 * THE DATES WERE FITTED, NOT REWRITTEN: the sheet ran from the bid result on
 * 25 Sep to 22 Dec — after the conference itself, whose Day 0/Day 1 it put on
 * 2–3 Dec. Everything up to the 1st OC meeting (25 Sep – 6 Oct) keeps its exact
 * date; everything from 7 Oct onwards keeps its ORDER and relative spacing,
 * compressed so the last preparation lands on 1 Dec and Day 0–3 are 2–5 Dec.
 * That puts the nine checkpoints exactly five days apart (18 Oct → 27 Nov).
 * Every timeline row keeps its sheet date in `original`, shown in edit mode.
 *
 * The Checkpoints tab carried its own, different dates (30 Sep → 25 Nov) that
 * contradicted the timeline; its deliverables are kept, its dates follow the
 * timeline's checkpoints.
 *
 * This runs ONCE, on an empty database (src/server/activation.ts); after that
 * the database is the plan and this file is history.
 */

